54	@RestController
55	@CrossOrigin(exposedHeaders = "errors, content-type")
56	@RequestMapping("/api")
57	public class OwnerRestControllerV1 implements OwnersApi {
58	
59	    /**
60	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
61	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
62	     */
63	    private static final Pattern EMAIL_PATTERN =
64	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
65	
66	    private final ClinicService clinicService;
67	
68	    private final OwnerMapper ownerMapper;
69	
70	    private final PetMapper petMapper;
71	
72	    private final VisitMapper visitMapper;
73	
74	    public OwnerRestControllerV1(ClinicService clinicService,
75	                                 OwnerMapper ownerMapper,
76	                                 PetMapper petMapper,
77	                                 VisitMapper visitMapper) {
78	        this.clinicService = clinicService;
79	        this.ownerMapper = ownerMapper;
80	        this.petMapper = petMapper;
81	        this.visitMapper = visitMapper;
82	    }
83	
84	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
85	    @Override
86	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
87	        Collection<Owner> owners;
88	        if (lastName != null) {
89	            owners = this.clinicService.findOwnerByLastName(lastName);
90	        } else {
91	            owners = this.clinicService.findAllOwners();
92	        }
93	        if (owners.isEmpty()) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
102	        Owner owner = this.clinicService.findOwnerById(ownerId);
103	        if (owner == null) {
104	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
105	        }
106	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
107	    }
108	
109	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
110	    @Override
111	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        String telephone = toE164(owner.getTelephone());
115	        if (telephone == null) {
116	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
117	        }
118	        owner.setTelephone(telephone);
119	        if (owner.getRegistrationDate() == null) {
120	            owner.setRegistrationDate(LocalDate.now());
121	        }
122	        if (owner.getEmail() != null) {
123	            String email = normalizeEmail(owner.getEmail());
124	            if (!EMAIL_PATTERN.matcher(email).matches()) {
125	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	            }
127	            owner.setEmail(email);
128	        }
129	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
130	            .anyMatch(existing -> telephone.equals(toE164(existing.getTelephone())));
131	        if (telephoneInUse) {
132	            return new ResponseEntity<>(HttpStatus.CONFLICT);
133	        }
134	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
135	            String lastNameKey = householdKey(owner.getLastName());
136	            String addressKey = householdKey(owner.getAddress());
137	            boolean householdInUse = this.clinicService.findAllOwners().stream()
138	                .anyMatch(existing -> lastNameKey.equals(householdKey(existing.getLastName()))
139	                    && addressKey.equals(householdKey(existing.getAddress())));
140	            if (householdInUse) {
141	                return new ResponseEntity<>(HttpStatus.CONFLICT);
142	            }
143	        }
144	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
145	        this.clinicService.saveOwner(owner);
146	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
147	        headers.setLocation(UriComponentsBuilder.newInstance()
148	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
149	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
150	    }
151	
152	    /**
153	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
154	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
155	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
156	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}.
157	     *
158	     * @param telephone the raw telephone value (may be {@code null})
159	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
160	     *         a valid E.164 number
161	     */
162	    private String toE164(String telephone) {
163	        if (telephone == null) {
164	            return null;
165	        }
166	        String trimmed = telephone.trim();
167	        boolean hasCountryCode = trimmed.startsWith("+");
168	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
169	        if (hasCountryCode) {
170	            cleaned = cleaned.substring(1);
171	        }
172	        if (!cleaned.matches("[0-9]+")) {
173	            return null;
174	        }
175	        String digits;
176	        if (hasCountryCode) {
177	            digits = cleaned;
178	        } else {
179	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
180	            digits = "61" + national;
181	        }
182	        if (digits.length() < 8 || digits.length() > 15) {
183	            return null;
184	        }
185	        return "+" + digits;
186	    }
187	
188	    /**
189	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
190	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
191	     *
192	     * @param email the raw email value (must not be {@code null})
193	     * @return the trimmed, lower-cased email
194	     */
195	    private String normalizeEmail(String email) {
196	        return email.trim().toLowerCase(Locale.ROOT);
197	    }
198	
199	    /**
200	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
201	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
202	     * so that owners are compared case-insensitively with collapsed whitespace.
203	     *
204	     * @param value the raw value (must not be {@code null})
205	     * @return the normalized comparison key
206	     */
207	    private String householdKey(String value) {
208	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
209	    }
210	
211	    /**
212	     * Builds the customer code for a newly registered owner in the form
213	     * {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the upper-cased first three letters
214	     * of the last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to
215	     * one more than the current number of owners (e.g. {@code 'SMI-0007'}).
216	     *
217	     * @param lastName the owner's last name
218	     * @return the assigned customer code
219	     */
220	    private String nextCustomerCode(String lastName) {
221	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
222	        int sequence = this.clinicService.findAllOwners().size() + 1;
223	        return String.format(Locale.ROOT, "%s-%04d", last3, sequence);
224	    }
225	
226	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
227	    @Override
228	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
229	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
230	        if (currentOwner == null) {
231	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
232	        }
233	        String email = ownerFieldsDto.getEmail();
234	        if (email != null) {
235	            email = normalizeEmail(email);
236	            if (!EMAIL_PATTERN.matcher(email).matches()) {
237	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
238	            }
239	        }
240	        String telephone = toE164(ownerFieldsDto.getTelephone());
241	        if (telephone == null) {
242	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
243	        }
244	        currentOwner.setAddress(ownerFieldsDto.getAddress());
245	        currentOwner.setCity(ownerFieldsDto.getCity());
246	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
247	        currentOwner.setLastName(ownerFieldsDto.getLastName());
248	        currentOwner.setTelephone(telephone);
249	        currentOwner.setEmail(email);
250	        this.clinicService.saveOwner(currentOwner);
251	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
252	    }
253	
254	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
255	    @Transactional
256	    @Override
257	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
258	        Owner owner = this.clinicService.findOwnerById(ownerId);
259	        if (owner == null) {
260	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
261	        }
262	        this.clinicService.deleteOwner(owner);
263	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
264	    }
265	
266	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
267	    @Override
268	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
269	        Owner owner = this.clinicService.findOwnerById(ownerId);
270	        if (owner == null) {
271	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
272	        }
273	        HttpHeaders headers = new HttpHeaders();
274	        Pet pet = petMapper.toPet(petFieldsDto);
275	        owner.setId(ownerId);
276	        pet.setOwner(owner);
277	        pet.getType().setName(null);
278	        this.clinicService.savePet(pet);
279	        PetDto petDto = petMapper.toPetDto(pet);
280	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
281	            .buildAndExpand(pet.getId()).toUri());
282	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
283	    }
284	
285	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
286	    @Override
287	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
288	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
289	        if (currentOwner != null) {
290	            Pet currentPet = this.clinicService.findPetById(petId);
291	            if (currentPet != null) {
292	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
293	                currentPet.setName(petFieldsDto.getName());
294	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
295	                this.clinicService.savePet(currentPet);
296	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
297	            }
298	        }
299	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
300	    }
301	
302	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
303	    @Override
304	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
305	        HttpHeaders headers = new HttpHeaders();
306	        Visit visit = visitMapper.toVisit(visitFieldsDto);
307	        Pet pet = new Pet();
308	        pet.setId(petId);
309	        visit.setPet(pet);
310	        this.clinicService.saveVisit(visit);
311	        VisitDto visitDto = visitMapper.toVisitDto(visit);
312	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
313	            .buildAndExpand(visit.getId()).toUri());
314	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
315	    }
316	
317	
318	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
319	    @Override
320	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
321	        Owner owner = this.clinicService.findOwnerById(ownerId);
322	        if (owner != null) {
323	            Pet pet = owner.getPet(petId);
324	            if (pet != null) {
325	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
326	            }
327	        }
328	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
329	    }
330	}
