27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
61	    private Set<Pet> pets;
62	
63	    public String getAddress() {
64	        return this.address;
65	    }
66	
67	    public void setAddress(String address) {
68	        this.address = address;
69	    }
70	
71	    public String getCity() {
72	        return this.city;
73	    }
74	
75	    public void setCity(String city) {
76	        this.city = city;
77	    }
78	
79	    public String getTelephone() {
80	        return this.telephone;
81	    }
82	
83	    public void setTelephone(String telephone) {
84	        this.telephone = telephone;
85	    }
86	
87	    public String getEmail() {
88	        return this.email;
89	    }
90	
91	    public void setEmail(String email) {
92	        this.email = email;
93	    }
94	
95	    public LocalDate getRegistrationDate() {
96	        return this.registrationDate;
97	    }
98	
99	    public void setRegistrationDate(LocalDate registrationDate) {
100	        this.registrationDate = registrationDate;
101	    }
102	
103	    public String getCustomerCode() {
104	        return this.customerCode;
105	    }
106	
107	    public void setCustomerCode(String customerCode) {
108	        this.customerCode = customerCode;
109	    }
110	
111	    /**
112	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
113	     *
114	     * @return the formatted display name
115	     */
116	    public String getDisplayName() {
117	        return this.getLastName() + ", " + this.getFirstName();
118	    }
119	
120	    /**
121	     * The owner's initials: the upper-cased first letters of the first and last
122	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
123	     *
124	     * @return the formatted initials
125	     */
126	    public String getInitials() {
127	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
128	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
129	    }
130	
131	    protected Set<Pet> getPetsInternal() {
132	        if (this.pets == null) {
133	            this.pets = new HashSet<>();
134	        }
135	        return this.pets;
136	    }
137	
138	    protected void setPetsInternal(Set<Pet> pets) {
139	        this.pets = pets;
140	    }
141	
142	    public List<Pet> getPets() {
143	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
144	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
145	        return Collections.unmodifiableList(sortedPets);
146	    }
147	
148	    public void setPets(List<Pet> pets) {
149	        this.pets = new HashSet<>(pets);
150	    }
151	
152	    public void addPet(Pet pet) {
153	        getPetsInternal().add(pet);
154	        pet.setOwner(this);
155	    }
156	
157	    /**
158	     * Return the Pet with the given name, or null if none found for this Owner.
159	     *
160	     * @param name to test
161	     * @return true if pet name is already in use
162	     */
163	    public Pet getPet(String name) {
164	        return getPet(name, false);
165	    }
166	
167	    /**
168	     * Return the Pet with the given name, or null if none found for this Owner.
169	     *
170	     * @param name to test
171	     * @return true if pet name is already in use
172	     */
173	    public Pet getPet(String name, boolean ignoreNew) {
174	        name = name.toLowerCase();
175	        for (Pet pet : getPetsInternal()) {
176	            if (!ignoreNew || !pet.isNew()) {
177	                String compName = pet.getName();
178	                compName = compName.toLowerCase();
179	                if (compName.equals(name)) {
180	                    return pet;
181	                }
182	            }
183	        }
184	        return null;
185	    }
186	
187	    public Pet getPet(Integer petId) {
188	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
189	    }
190	
191	    @Override
192	    public String toString() {
193	        return new ToStringCreator(this)
194	
195	            .append("id", this.getId())
196	            .append("new", this.isNew())
197	            .append("lastName", this.getLastName())
198	            .append("firstName", this.getFirstName())
199	            .append("address", this.address)
200	            .append("city", this.city)
201	            .append("telephone", this.telephone)
202	            .append("email", this.email)
203	            .toString();
204	    }
205	}
